#ifndef MARKS_H
#define MARKS_H

#define MAX_STUDENTS 100
#define NAME_LEN 32

typedef struct {
    char name[NAME_LEN];
    int marks;
} Student;

typedef struct {
    Student list[MAX_STUDENTS];
    int count;
} Class;

/* 0 on success; -1 class full; -2 marks outside 0-100; -3 name already added. */
int class_add(Class *c, const char *name, int marks);
/* Average of all marks, or 0.0 for an empty class. */
double class_average(const Class *c);
/* Index of the highest mark (the first one entered on a tie), or -1 if empty. */
int class_top_index(const Class *c);
/* counts[0..3] = number of A (>= 80), B (>= 60), C (>= 40), F (< 40). */
void class_grades(const Class *c, int counts[4]);
/* Fills order[0..count-1] with indexes sorted by marks high to low, then name A to Z. */
void class_ranking(const Class *c, int order[]);

#endif

#include <string.h>
#include "marks.h"

int class_add(Class *c, const char *name, int marks) {
    /* Milestone 1 */
    (void)c; (void)name; (void)marks;
    return 0;
}

double class_average(const Class *c) {
    (void)c;
    return 0.0;   /* Milestone 1 */
}

int class_top_index(const Class *c) {
    (void)c;
    return -1;    /* Milestone 1 */
}

void class_grades(const Class *c, int counts[4]) {
    (void)c;
    for (int g = 0; g < 4; g++) counts[g] = 0;   /* Milestone 2 */
}

void class_ranking(const Class *c, int order[]) {
    for (int i = 0; i < c->count; i++) order[i] = i;   /* Milestone 3: sort these */
}

#include <stdio.h>
#include <string.h>
#include "marks.h"

int main(void) {
    static Class cls;
    char line[128], cmd[16], name[64];
    int n;
    while (fgets(line, sizeof line, stdin) != NULL) {
        if (sscanf(line, "%15s", cmd) != 1) continue;
        if (strcmp(cmd, "ADD") == 0 && sscanf(line, "%*s %63s %d", name, &n) == 2) {
            int r = strlen(name) >= NAME_LEN ? -4 : class_add(&cls, name, n);
            if (r == 0) printf("added %s\n", name);
            else if (r == -1) printf("error: class full\n");
            else if (r == -2) printf("error: marks must be 0-100\n");
            else if (r == -3) printf("error: %s already added\n", name);
            else printf("error: name too long\n");
        } else if (strcmp(cmd, "STATS") == 0) {
            int t = class_top_index(&cls);
            if (t < 0) printf("no students\n");
            else printf("count %d, average %.1f, highest %s %d\n", cls.count, class_average(&cls), cls.list[t].name, cls.list[t].marks);
        } else if (strcmp(cmd, "GRADES") == 0) {
            int g[4];
            class_grades(&cls, g);
            printf("A %d B %d C %d F %d\n", g[0], g[1], g[2], g[3]);
        } else if (strcmp(cmd, "TOP") == 0 && sscanf(line, "%*s %d", &n) == 1 && n > 0) {
            int order[MAX_STUDENTS];
            class_ranking(&cls, order);
            if (cls.count == 0) printf("no students\n");
            for (int i = 0; i < n && i < cls.count; i++) printf("%d. %s %d\n", i + 1, cls.list[order[i]].name, cls.list[order[i]].marks);
        } else {
            line[strcspn(line, "\n")] = '\0';
            printf("error: bad command %s\n", line);
        }
    }
    return 0;
}

