#include <string.h>
#include "marks.h"

int class_add(Class *c, const char *name, int marks) {
    if (c->count == MAX_STUDENTS) return -1;
    if (marks < 0 || marks > 100) return -2;
    for (int i = 0; i < c->count; i++)
        if (strcmp(c->list[i].name, name) == 0) return -3;
    Student *s = &c->list[c->count++];
    strncpy(s->name, name, NAME_LEN - 1);
    s->name[NAME_LEN - 1] = '\0';
    s->marks = marks;
    return 0;
}

double class_average(const Class *c) {
    if (c->count == 0) return 0.0;
    long sum = 0;
    for (int i = 0; i < c->count; i++) sum += c->list[i].marks;
    return (double)sum / c->count;
}

int class_top_index(const Class *c) {
    int best = -1;
    for (int i = 0; i < c->count; i++)
        if (best < 0 || c->list[i].marks > c->list[best].marks) best = i;
    return best;
}

void class_grades(const Class *c, int counts[4]) {
    for (int g = 0; g < 4; g++) counts[g] = 0;
    for (int i = 0; i < c->count; i++) {
        int m = c->list[i].marks;
        counts[m >= 80 ? 0 : m >= 60 ? 1 : m >= 40 ? 2 : 3]++;
    }
}

static int before(const Class *c, int a, int b) {
    if (c->list[a].marks != c->list[b].marks) return c->list[a].marks > c->list[b].marks;
    return strcmp(c->list[a].name, c->list[b].name) < 0;
}

void class_ranking(const Class *c, int order[]) {
    for (int i = 0; i < c->count; i++) order[i] = i;
    for (int i = 1; i < c->count; i++) {          /* insertion sort: at most 100 students */
        int k = order[i], j = i - 1;
        while (j >= 0 && before(c, k, order[j])) {
            order[j + 1] = order[j];
            j--;
        }
        order[j + 1] = k;
    }
}
